import hou
from pxr import UsdGeom

karma = hou.node("/stage/karma_render")
stage = karma.stage()

# Check dome light attributes
dome = stage.GetPrimAtPath("/lights/env_light")
dome_attrs = {}
if dome:
    for attr in dome.GetAttributes():
        name = attr.GetName()
        if any(k in name.lower() for k in ['intens', 'expos', 'color', 'texture', 'file']):
            val = attr.Get()
            dome_attrs[name] = str(val)

# Check key light
key = stage.GetPrimAtPath("/lights/key_light")
key_attrs = {}
if key:
    for attr in key.GetAttributes():
        name = attr.GetName()
        if any(k in name.lower() for k in ['intens', 'expos', 'color', 'angle']):
            val = attr.Get()
            key_attrs[name] = str(val)

# Check render settings camera
render = stage.GetPrimAtPath("/Render/rendersettings")
render_attrs = {}
if render:
    for attr in render.GetAttributes():
        name = attr.GetName()
        if 'camera' in name.lower():
            render_attrs[name] = str(attr.Get())

result = {"dome": dome_attrs, "key": key_attrs, "render_settings": render_attrs}

